// who plays which phrase: [start beat, phrase, transpose, stretch (2 = half speed)]
const LEAD = [[0,"REST",0,1],[32,"REST",0,1],[64,"A",0,1],[96,"A",0,1],[128,"A",0,1],[160,"REST",0,1],[224,"REST",0,1],[288,"A",0,1],[320,"A",0,1],[352,"A",0,2]]
const LEAD2 = [[0,"REST",0,1],[32,"B",0,1],[48,"B",0,1],[64,"REST",0,1],[160,"B",0,1],[176,"B",0,1],[192,"B",0,1],[208,"B",0,1],[224,"BRIDGE",0,1],[240,"BRIDGE",0,1],[256,"BRIDGE",0,1],[272,"BRIDGE",0,1],[288,"REST",0,1],[352,"REST",0,1]]
const COUNTER = [[0,"REST",0,1],[32,"REST",0,1],[64,"REST",0,1],[160,"REST",0,1],[224,"REST",0,1],[288,"HARMONY",0,1],[352,"REST",0,1]]
// the note of a voice at x → { n, d, τ, u, at } or null
function voiceAt(plan, x) {
  if (x >= END) return null
  let row = null
  for (const r of plan) if (r[0] <= x) row = r
  if (!row) return null
  const [s, name, tr, k] = row, m = notesAt(PHRASES[name] ?? REST, (x - s) / k)
  return m && { n: m.n + tr, d: m.d * k, τ: m.τ * k, u: m.u, at: s + m.at * k }
}
const leadAt = x => voiceAt(LEAD, x)
const lead2At = x => voiceAt(LEAD2, x)
// the counter-voice: HARMONY = the highest chord tone at least a third below the lead (computed from
// the chords); CANON = the lead itself two beats later, an octave down
const counterAt = x => {
  let row = null
  for (const r of COUNTER) if (r[0] <= x) row = r
  if (!row || x >= END) return null
  if (row[1] === 'CANON') {
    const m = x - 2 >= row[0] ? leadAt(x - 2) : null
    return m && { ...m, n: m.n - 12, at: m.at + 2 }
  }
  if (row[1] !== 'HARMONY') return null
  const m = leadAt(x), c = chordAt(x)
  if (!m || !c) return null
  const pcs = c[3].map(n => mod(n, 12))
  for (let n = m.n - 3; n > m.n - 12; n--) if (pcs.includes(mod(n + 60, 12))) return { ...m, n }
  return null
}

// ---- nightlead ---------------------------------------------------------------------------------
const track0 = {
  color: '#b8d8ff',
  graph: x => { const m = leadAt(x); return m ? 1.1 + (m.n + 5) * 0.0559 : null },
  midi: x => { const m = leadAt(x); return m && m.u < 0.92 ? [60 + m.n] : [] },
  formula: ["R(f,t) = g\\sum_k a_k(f)\\,\\min\\!\\big(1, \\tfrac{t}{\\tau_k}\\big)\\big(s_k + (1 - s_k)e^{-d_k(f)\\,t}\\big)\\sin 2\\pi r_k f\\,(1 + \\nu(t))\\,t + \\sum_b n_b\\,\\BP_{f_b}\\eta","r_k = 0.9991,\\ 2.01,\\ 3,\\ 4.03,\\ 6.04\\ldots\\quad \\text{— измерено по 3 нотам записи; } a_k(f)\\ \\text{по номеру и по частоте (форманты), } d_k \\text{ по кривой затухания}","\\nu(t) = 2^{5.75\\min(1, (t - 0.14)^+/0.35)\\sin(2\\pi\\cdot 4.05t)/1200} - 1\\quad\\text{— вибрато}"],
  audio({ bpm }) {
    const sec = 60 / bpm, p = poly(resynthTone({"kind":"sustained","f0":524,"B":0.0008,"wF":0.63,"p":[[0.9991,0.4253,0.369,0,1],[2.01,0.1357,0.369,0,1],[3,0.0086,0.369,0.172,0.9344],[4.03,0.0254,0.369,0,1],[6.04,0.0048,0.369,0,1]],"fa":[[349,-0.48],[524,-7.43],[587,-7.66],[707,-1.39],[1051,-17.35],[1182,-12.7],[1488,-21.52],[1930,-31.9],[3164,-46.43],[3564,-42]],"fd":[[349,0.5283],[587,0.085],[707,0.6121],[1047,0.5464],[1182,0.5243],[1571,0.172],[1763,0.2321]],"attack":0.369,"release":0.25,"vib":{"rate":4.05,"depth":5.75,"delay":0.14},"scoop":0.97,"noise":{"atk":[0,0,0,0,0,0,0],"sus":[0.0001,0.0016,0.0008,0.0002,0.0002,0.0002,0.0002],"dec":0.02},"notes":3}), { release: 0.4, life: 30 }), fire = trigger()
    const echo = delay({ time: sec * 1.5, feedback: 0.35, wet: 0.22 }), verb = reverb({ room: 0.94, damp: 0.3, wet: 0.42 })
    return x => {
      const m = leadAt(x)
      if (fire(m ? m.at : null)) p.hit(hz(m.n, C4), 0.78, m.d * sec)
      const y = 1.2 * p()
      return verb(...echo(...pan(y, 0.12)))
    }
  },
}

// ---- choir -------------------------------------------------------------------------------------
const track1 = {
  color: '#e0c8ff',
  graph: x => { const m = lead2At(x); return m ? 1 + (m.n + 5) * 0.0559 : null },
  midi: x => { const m = lead2At(x); return m && m.u < 0.92 ? [60 + m.n] : [] },
  formula: ["Ch = \\sum_{i=1}^{3} \\tfrac{G_i}{Q_i}\\,\\BP_{F_i}\\big(\\saw(f) + 0.05\\eta\\big),\\quad F:\\ \\text{«а»} \\to \\text{«о»}"],
  audio({ bpm }) {
    const sec = 60 / bpm, v = voice({ size: 1, breath: 0.06 }), v2 = voice({ size: 0.94, breath: 0.06 }), glide = smooth(60), verb = reverb({ room: 0.9, wet: 0.5 })
    let n = 0
    return x => {
      const m = lead2At(x), t = x * sec
      if (m) n = m.n
      const F = blend(VOWELS.a, VOWELS.o, 0.5 + 0.5 * sin(TAU * x / 8)), vib = 0.15 * sin(TAU * 5 * t)
      const on = m && m.u < 0.95 ? 1 : 0, f = glide(hz(n + vib, C4))
      return verb(0.3465 * v(f, F, on), 0.3465 * v2(f * 1.004, F, on))
    }
  },
}

